<template>
  <section class="evidence-page" aria-labelledby="evidence-title">
    <div class="page-heading"><div><p class="eyebrow">证据与覆盖度</p><h2 id="evidence-title">任务证据链</h2><p class="page-description">当前、未来和未确定结果分开呈现，PARTIAL/UNKNOWN 不会被当作全范围无匹配。</p></div><el-button @click="$router.back()">返回任务</el-button></div>
    <el-alert v-if="errorMessage" :title="errorMessage" type="warning" :closable="false" show-icon />
    <el-tabs v-else v-model="activeTab"><el-tab-pane label="当前/未来事实" name="snapshots"><el-table :data="overview.snapshots" stripe><el-table-column prop="sourceObjectType" label="对象类型" /><el-table-column prop="sourceObjectKey" label="对象标识" /><el-table-column prop="effectiveClass" label="生效分类" /><el-table-column prop="checkedAt" label="checked_at" /><el-table-column prop="sourceVersion" label="来源版本" /><el-table-column prop="resultDigest" label="结果摘要" /></el-table><el-empty v-if="!overview.snapshots.length" description="暂无事实快照" /></el-tab-pane><el-tab-pane label="覆盖度" name="coverage"><el-table :data="overview.coverages" stripe><el-table-column prop="completeness" label="覆盖状态" /><el-table-column prop="traversedPaths" label="已遍历路径" /><el-table-column prop="uncoveredPaths" label="路径缺口" /><el-table-column prop="observedTotal" label="已观察数量" /><el-table-column prop="resultSetDigest" label="结果摘要" /></el-table><el-empty v-if="!overview.coverages.length" description="暂无覆盖记录" /></el-tab-pane><el-tab-pane label="发现与见证" name="findings"><el-card v-for="finding in overview.findings" :key="finding.findingId" shadow="never" class="finding-card"><div class="finding-heading"><el-tag>{{ finding.effectiveClass }}</el-tag><el-tag type="info">{{ finding.status }}</el-tag><span>{{ finding.findingType }}</span></div><p>{{ finding.statement }}</p><dl v-if="finding.witness" class="witness-summary"><dt>算法版本</dt><dd>{{ finding.witness.algorithmVersion }}</dd><dt>规则版本</dt><dd>{{ finding.witness.ruleSetVersion }}</dd><dt>复算状态</dt><dd>{{ finding.witness.recomputeStatus }}</dd><dt>输入摘要</dt><dd class="mono">{{ finding.witness.inputDigest }}</dd><dt>输出摘要</dt><dd class="mono">{{ finding.witness.outputDigest }}</dd></dl><el-alert v-else-if="finding.judgmentMode === 'DETERMINISTIC'" title="该确定性判断暂无计算见证，不能发布" type="warning" :closable="false" /><div v-if="finding.confirmation" class="confirmation-summary"><p>已记录专业决定：{{ finding.confirmation.decision }}，确认时间：{{ finding.confirmation.confirmedAt }}</p><p>理由：{{ finding.confirmation.rationale }}</p><p>证据引用：{{ finding.confirmation.evidenceRefs }}</p></div><el-form v-else-if="finding.judgmentMode !== 'DETERMINISTIC'" label-position="top" class="confirmation-form"><el-form-item label="专业决定"><el-select v-model="drafts[finding.findingId].decision"><el-option label="确认" value="CONFIRM" /><el-option label="拒绝" value="REJECT" /><el-option label="需要更多证据" value="NEEDS_MORE_EVIDENCE" /></el-select></el-form-item><el-form-item label="理由"><el-input v-model.trim="drafts[finding.findingId].rationale" type="textarea" :rows="3" maxlength="2000" show-word-limit /></el-form-item><el-form-item label="证据引用"><el-input v-model.trim="drafts[finding.findingId].evidenceRefs" placeholder="填写快照或来源引用标识" /></el-form-item><el-button type="primary" :loading="submitting === finding.findingId" @click="submitConfirmation(finding)">提交该条专业确认</el-button></el-form></el-card><el-empty v-if="!overview.findings.length" description="暂无发现" /></el-tab-pane></el-tabs>
  </section>
</template>
<script lang="ts">
import Vue from 'vue'
import { EvidenceOverview as EvidenceOverviewType } from '../api/generated'
import { confirmFinding, fetchEvidenceOverview } from '../services/evidence-api'
import { EvidenceFinding } from '../api/generated'

export default Vue.extend({
  name: 'EvidenceOverview',
  data() { return { overview: { taskId: '', snapshots: [], coverages: [], findings: [] } as EvidenceOverviewType, activeTab: 'snapshots', errorMessage: '', submitting: '', drafts: {} as Record<string, { decision: 'CONFIRM' | 'REJECT' | 'NEEDS_MORE_EVIDENCE'; rationale: string; evidenceRefs: string }> } },
  async created() { await this.loadOverview() },
  methods: {
    /** 加载当前任务证据链并将越权或失败转为中文提示。 */
    async loadOverview(): Promise<void> { try { this.overview = await fetchEvidenceOverview(String(this.$route.params.taskId)); this.overview.findings.forEach((finding) => { if (!this.drafts[finding.findingId]) this.$set(this.drafts, finding.findingId, { decision: 'CONFIRM', rationale: '', evidenceRefs: '' }) }) } catch (error: unknown) { this.errorMessage = error instanceof Error ? error.message : '证据查询未完成，请稍后重试' } },
    async submitConfirmation(finding: EvidenceFinding): Promise<void> { const draft = this.drafts[finding.findingId]; if (!draft || !draft.rationale.trim() || !draft.evidenceRefs.trim()) { this.errorMessage = '请填写专业决定、理由和证据引用'; return }; this.submitting = finding.findingId; this.errorMessage = ''; try { await confirmFinding(this.overview.taskId, finding.findingId, { scopeRevisionId: finding.scopeRevisionId, decision: draft.decision, rationale: draft.rationale, evidenceRefs: draft.evidenceRefs }); await this.loadOverview() } catch (error: unknown) { this.errorMessage = error instanceof Error ? error.message : '专业确认未完成，请稍后重试' } finally { this.submitting = '' } },
  },
})
</script>
